class Solution { string labels;vector<int> answer;vector<vector<int>> graph;array<int,26> dfs(int node,int parent){array<int,26> count{};++count[labels[node]-'a'];for(int child:graph[node])if(child!=parent){auto childCount=dfs(child,node);for(int letter=0;letter<26;++letter)count[letter]+=childCount[letter];}answer[node]=count[labels[node]-'a'];return count;}public:vector<int> countSubTrees(int n,vector<vector<int>>& edges,string labels){this->labels=labels;answer.resize(n);graph.resize(n);for(auto& edge:edges){graph[edge[0]].push_back(edge[1]);graph[edge[1]].push_back(edge[0]);}dfs(0,-1);return answer;} };
